export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const height = launchSpeed * time - 0.5 * gravity * time * time;
  const velocity = launchSpeed - gravity * time;

  let motionStateText = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    motionStateText = "Still for an instant";
  } else if (velocity < 0) {
    motionStateText = "Moving down";
  }

  const maxH = (launchSpeed * launchSpeed) / (2 * gravity);
  const scaleY = 250 / Math.max(maxH * 1.2, 2.5);
  const baseY = 320;
  const ballY = baseY - height * scaleY;
  const ballX = 320;

  const objects = [];

  objects.push(sdk.panel({ x: 40, y: 30, w: 560, h: 360, title: "Lane: Toss Motion", state: motionStateText, id: "lane.toss" }));
  objects.push(sdk.axis("axis.height", { x: 100, y: 320, length: 260, orientation: "y", min: 0, max: Math.max(maxH * 1.2, 2.5), label: "Height", unit: "m" }));
  objects.push(sdk.groundMark("ground", ballX, baseY, 60, "Launch"));

  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { role: "output" }));

  if (Math.abs(velocity) >= 0.05) {
    objects.push(sdk.vector("vec.v", { x: ballX + 20, y: ballY }, { value: velocity, direction: "up" }, { scale: 8, minLength: 12, label: "v", role: "output" }));
  }

  objects.push(sdk.vector("vec.a", { x: ballX - 20, y: ballY }, { value: -gravity, direction: "up" }, { scale: 8, minLength: 12, label: "a", role: "warning" }));

  let calloutLines = [motionStateText, "Gravity pulls down"];
  objects.push(sdk.callout(ballX + 45, ballY - 20, calloutLines, { id: "callout.toss" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateText },
        { id: "gravityState", value: "Gravity pulls down" }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime: launchSpeed / gravity,
      apexHeight: maxH,
      velocity,
      height
    }
  };
}
